//! 🪢️ Final root identities group repeated nested patches without copying page or story content.
use crate::*;
use semio_s_artifact_layout_layout_model::{Page,TextStory,snapshot::LayoutSnapshot};
use semio_framework_os_kernel::ApplyCapability;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep}};
use super::{collections::RootCollections,page::PageWork,story::StoryWork,super::keyed_plan::{Origin,PlanAdvance}};
use std::mem::size_of;
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"Layout nested grouping phase is invalid")}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:256,depth:1,..Default::default()}}
fn paid()->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:256,..Default::default()}}
fn page<'a>(post:&'a LayoutSnapshot,d:&'a LayoutPagesDelta,origin:Origin)->&'a Page{if origin.inserted{&d.inserted[origin.index].row}else{&post.pages[origin.index]}}
fn story<'a>(post:&'a LayoutSnapshot,d:&'a LayoutStoriesDelta,origin:Origin)->&'a TextStory{if origin.inserted{&d.inserted[origin.index].row}else{&post.stories[origin.index]}}
/// 🔢 Group indices are fully reserved before their source rows enter any commit frontier.
pub struct NestedWork{pages:Vec<PageWork>,stories:Vec<StoryWork>,page_map:Vec<usize>,story_map:Vec<usize>,phase:u8,index:usize,kind:usize,commit_phase:u8,closing:bool,page_closing:bool,story_closing:bool}
impl Default for NestedWork{fn default()->Self{Self{pages:Vec::new(),stories:Vec::new(),page_map:Vec::new(),story_map:Vec::new(),phase:0,index:0,kind:0,commit_phase:0,closing:false,page_closing:false,story_closing:false}}}
impl NestedWork{
 pub fn preflight_demand(&self,d:&LayoutDiff,post:&LayoutSnapshot,roots:&RootCollections)->Result<RetirementDemand,ValueError>{Ok(match self.phase{
  0=>{let(p,s)=(roots.pages.origins().map_or(0,|v|v.len()),roots.stories.origins().map_or(0,|v|v.len()));let(pm,sm)=(d.pages.as_ref().map_or(0,|v|v.modified.len()),d.stories.as_ref().map_or(0,|v|v.modified.len()));RetirementDemand{capacity_bytes:p*size_of::<usize>()+s*size_of::<usize>()+p.min(pm)*size_of::<PageWork>()+s.min(sm)*size_of::<StoryWork>(),..fixed()}},
  5=>if let Some(group)=self.pages.get(self.index){RetirementDemand{capacity_bytes:group.counts[self.kind]*size_of::<usize>(),..fixed()}}else{fixed()},
  6=>if let Some(group)=self.stories.get(self.index){RetirementDemand{capacity_bytes:group.count*size_of::<usize>(),..fixed()}}else{fixed()},
  9=>if let Some(group)=self.pages.get(self.index){group.preflight_demand(page(post,d.pages.as_ref().ok_or_else(fault)?,group.origin),d.pages.as_ref().unwrap())?}else{fixed()},
  10=>if let Some(group)=self.stories.get(self.index){group.preflight_demand(story(post,d.stories.as_ref().ok_or_else(fault)?,group.origin),d.stories.as_ref().unwrap())?}else{fixed()},
  3=>RetirementDemand{copy_bytes:size_of::<PageWork>()*2+256,..fixed()},4=>RetirementDemand{copy_bytes:size_of::<StoryWork>()*2+256,..fixed()},1|2|7|8|11=>fixed(),_=>return Err(fault())})}
 pub fn preflight(&mut self,d:&LayoutDiff,post:&LayoutSnapshot,roots:&RootCollections,g:RetainedCloneGrant)->Result<PlanAdvance,ValueError>{let demand=self.preflight_demand(d,post,roots)?;let mut out=PlanAdvance{done:false,error:None,progress:Default::default()};if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,demand){return Ok(out)}out.progress=paid();match self.phase{
  0=>{let(p,s)=(roots.pages.origins().map_or(0,|v|v.len()),roots.stories.origins().map_or(0,|v|v.len()));let(pm,sm)=(d.pages.as_ref().map_or(0,|v|v.modified.len()),d.stories.as_ref().map_or(0,|v|v.modified.len()));let reserved=self.page_map.try_reserve_exact(p).and_then(|_|self.story_map.try_reserve_exact(s)).and_then(|_|self.pages.try_reserve_exact(p.min(pm))).and_then(|_|self.stories.try_reserve_exact(s.min(sm)));out.progress.retained_capacity_bytes=self.page_map.capacity()*size_of::<usize>()+self.story_map.capacity()*size_of::<usize>()+self.pages.capacity()*size_of::<PageWork>()+self.stories.capacity()*size_of::<StoryWork>();if reserved.is_err()||out.progress.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(out.progress))}self.phase=1},
  1=>if self.page_map.len()==roots.pages.origins().map_or(0,|v|v.len()){self.phase=2}else{self.page_map.push(usize::MAX)},
  2=>if self.story_map.len()==roots.stories.origins().map_or(0,|v|v.len()){self.phase=3;self.index=0}else{self.story_map.push(usize::MAX)},
  3=>{out.progress.copied_bytes=demand.copy_bytes;let n=d.pages.as_ref().map_or(0,|v|v.modified.len());if self.index==n{self.phase=4;self.index=0}else{let patch=&d.pages.as_ref().unwrap().modified[self.index].patch;let selected=std::array::from_fn::<_,4,_>(|k|PageWork::selected(patch,k));{let target=roots.pages.modification_targets().ok_or_else(fault)?[self.index];if self.page_map[target]==usize::MAX{self.page_map[target]=self.pages.len();let origin=roots.pages.origins().unwrap()[target].ok_or_else(fault)?;self.pages.push(PageWork::new(target,origin))}let group=&mut self.pages[self.page_map[target]];for k in 0..4{group.counts[k]+=usize::from(selected[k])}}self.index+=1}},
  4=>{out.progress.copied_bytes=demand.copy_bytes;let n=d.stories.as_ref().map_or(0,|v|v.modified.len());if self.index==n{self.phase=5;self.index=0;self.kind=0}else{if d.stories.as_ref().unwrap().modified[self.index].patch.style_runs.is_some(){let target=roots.stories.modification_targets().ok_or_else(fault)?[self.index];if self.story_map[target]==usize::MAX{self.story_map[target]=self.stories.len();let origin=roots.stories.origins().unwrap()[target].ok_or_else(fault)?;self.stories.push(StoryWork::new(target,origin))}self.stories[self.story_map[target]].count+=1}self.index+=1}},
  5=>if let Some(group)=self.pages.get_mut(self.index){let rows=&mut group.indices[self.kind];let reserved=rows.try_reserve_exact(group.counts[self.kind]);out.progress.retained_capacity_bytes=rows.capacity()*size_of::<usize>();if reserved.is_err()||out.progress.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(out.progress))}self.kind+=1;if self.kind==4{self.kind=0;self.index+=1}}else{self.phase=6;self.index=0},
  6=>if let Some(group)=self.stories.get_mut(self.index){let reserved=group.indices.try_reserve_exact(group.count);out.progress.retained_capacity_bytes=group.indices.capacity()*size_of::<usize>();if reserved.is_err()||out.progress.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(out.progress))}self.index+=1}else{self.phase=7;self.index=0},
  7=>{let n=d.pages.as_ref().map_or(0,|v|v.modified.len());if self.index==n{self.phase=8;self.index=0}else{let patch=&d.pages.as_ref().unwrap().modified[self.index].patch;let target=roots.pages.modification_targets().unwrap()[self.index];let group=self.page_map[target];if group!=usize::MAX{for k in 0..4{if PageWork::selected(patch,k){self.pages[group].indices[k].push(self.index)}}}self.index+=1}},
  8=>{let n=d.stories.as_ref().map_or(0,|v|v.modified.len());if self.index==n{self.phase=9;self.index=0}else{let target=roots.stories.modification_targets().unwrap()[self.index];if d.stories.as_ref().unwrap().modified[self.index].patch.style_runs.is_some(){let group=self.story_map[target];self.stories[group].indices.push(self.index)}self.index+=1}},
  9=>if let Some(group)=self.pages.get_mut(self.index){out=group.preflight(page(post,d.pages.as_ref().ok_or_else(fault)?,group.origin),d.pages.as_ref().unwrap(),g)?;if out.done{self.index+=1;out.done=false}}else{self.phase=10;self.index=0},
  10=>if let Some(group)=self.stories.get_mut(self.index){out=group.preflight(story(post,d.stories.as_ref().ok_or_else(fault)?,group.origin),d.stories.as_ref().unwrap(),g)?;if out.done{self.index+=1;out.done=false}}else{self.phase=11;self.index=0},11=>out.done=true,_=>return Err(fault())}Ok(out)}
 pub fn commit_demand(&self,roots:&RootCollections)->Result<RetirementDemand,ValueError>{match self.commit_phase{0=>if let Some(group)=self.pages.get(self.index){group.commit_demand(&roots.pages.staged().ok_or_else(fault)?.modified)}else{Ok(fixed())},1=>if let Some(group)=self.stories.get(self.index){group.commit_demand()}else{Ok(fixed())},2=>Ok(fixed()),_=>Err(fault())}}
 pub fn commit(&mut self,post:&mut LayoutSnapshot,roots:&mut RootCollections,g:RetainedCloneGrant,capability:ApplyCapability)->Result<RetainedCloneStep,ValueError>{let demand=self.commit_demand(roots)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,demand){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=paid();match self.commit_phase{0=>if let Some(group)=self.pages.get_mut(self.index){let owned=roots.pages.staged_mut(capability)?;let base=if group.origin.inserted{&mut owned.inserted[group.origin.index].row}else{&mut post.pages[group.origin.index]};let step=group.commit(base,&mut owned.modified,g,capability)?;p=step.progress();if matches!(step,RetainedCloneStep::Complete(_)){self.index+=1}}else{self.commit_phase=1;self.index=0},1=>if let Some(group)=self.stories.get_mut(self.index){let owned=roots.stories.staged_mut(capability)?;let base=if group.origin.inserted{&mut owned.inserted[group.origin.index].row}else{&mut post.stories[group.origin.index]};let step=group.commit(base,&mut owned.modified,g,capability)?;p=step.progress();if matches!(step,RetainedCloneStep::Complete(_)){self.index+=1}}else{self.commit_phase=2;self.index=0},2=>return Ok(RetainedCloneStep::Complete(p)),_=>return Err(fault())}Ok(RetainedCloneStep::Progress(p))}
 pub fn begin_close(&mut self){self.closing=true;self.page_closing=false;self.story_closing=false}
 fn capacity(&self)->usize{self.pages.capacity()*size_of::<PageWork>()+self.stories.capacity()*size_of::<StoryWork>()+self.page_map.capacity()*size_of::<usize>()+self.story_map.capacity()*size_of::<usize>()}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(group)=self.pages.last(){return if self.page_closing&&!group.terminal_is_empty(){group.close_demand(body)}else{Ok(RetirementDemand{copy_bytes:size_of::<PageWork>()*2+256,depth:1,..Default::default()})}}if let Some(group)=self.stories.last(){return if self.story_closing&&!group.terminal_is_empty(){group.close_demand(body)}else{Ok(RetirementDemand{copy_bytes:size_of::<StoryWork>()*2+256,depth:1,..Default::default()})}}Ok(RetirementDemand{release_bytes:if self.page_map.is_empty()&&self.story_map.is_empty(){self.capacity()}else{0},..fixed()})}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(fault())}let d=self.close_demand(g.maximum_copy_bytes)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if let Some(group)=self.pages.last_mut(){if !self.page_closing{group.begin_close();self.page_closing=true;return Ok(RetainedCloneStep::Progress(paid()))}if !group.terminal_is_empty(){return group.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}self.pages.pop();self.page_closing=false;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_bytes:d.copy_bytes,..paid()}))}if let Some(group)=self.stories.last_mut(){if !self.story_closing{group.begin_close();self.story_closing=true;return Ok(RetainedCloneStep::Progress(paid()))}if !group.terminal_is_empty(){return group.close_step(g).map(|step|RetainedCloneStep::Progress(step.progress()))}self.stories.pop();self.story_closing=false;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_bytes:d.copy_bytes,..paid()}))}if self.page_map.pop().is_some()||self.story_map.pop().is_some(){return Ok(RetainedCloneStep::Progress(paid()))}let released=self.capacity();self.pages=Vec::new();self.stories=Vec::new();self.page_map=Vec::new();self.story_map=Vec::new();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{released_bytes:released,..paid()}))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.pages.is_empty()&&self.stories.is_empty()&&self.page_map.is_empty()&&self.story_map.is_empty()&&self.capacity()==0}
}
impl Drop for NestedWork{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"nested root original owners need funded close")}}

impl NestedWork{
 pub fn final_page(&self,target:usize)->Option<&PageWork>{self.page_map.get(target).and_then(|&at|self.pages.get(at))}
 pub fn final_story(&self,target:usize)->Option<&StoryWork>{self.story_map.get(target).and_then(|&at|self.stories.get(at))}
}
